def split_words(txt):
    '''
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you should split on commas ',' if no commas exists you should return the number of lower case

    letters with odd order in the alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    Examples
    split_words("Hello world") ➞ ["Hello", "world!"]

    split_words("Hello,world") ➞ ["Hello", "world!"]
    split_words("abcdef") == 3 
    '''

def split_words(txt):
    if ' ' in txt:
        return txt.split(' ')
    elif ',' in txt:
        return txt.split(',')
    else:
        odd_count = sum(1 for char in txt.lower() if (ord(char) - ord('a')) % 2 == 1)
    return odd_count

# Test cases
